//! Links from findings to the rule reference page of the project site.

use a11y_rules::meta_for;

const RULE_REFERENCE: &str = "https://casoon.github.io/barrierlab/docs/a11y/reference/regeln/";

/// The anchor of a rule on the rule reference page: the finding ID with
/// every `/` replaced by `-` (`images/alt-missing` becomes
/// `images-alt-missing`).
///
/// The page `docs/a11y/reference/regeln.mdx` is generated by
/// `examples/a11y`, which calls this function for the anchor of each rule's
/// table row, so the two cannot drift apart.
pub fn rule_anchor(rule_id: &str) -> String {
    rule_id.replace('/', "-")
}

/// The URL of the rule's row on the rule reference page, or `None` for a
/// finding ID that `a11y-rules` does not declare (and that therefore has no
/// row there).
pub fn rule_help_url(rule_id: &str) -> Option<String> {
    meta_for(rule_id)?;
    Some(format!("{RULE_REFERENCE}#{}", rule_anchor(rule_id)))
}
